head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.STD_CD_APPL_ID = "";
scwin.arrPar = []; // fn_GetPar/getParam 전달 값 배열

// 표준코드 처리자 조회

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    try {
        const arrPar = new Array();
        ////var parentWin = $c.frame.path("../");
        const parentWin = $p.parent();

        ////var fn_GetPar = parentWin.fn_GetParam;
        scwin.fn_GetPar = parentWin.scwin.getParam;

        if (scwin.fn_GetPar !== undefined) {

            scwin.fn_GetPar(scwin.arrPar);
            scwin.param1 = ((scwin.arrPar.length >= 1) && (scwin.arrPar[0] !== undefined) ? scwin.arrPar[0] : "");
            //  param2  = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");

            scwin.ins_search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS93300.onpageload" });
    }
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.dts_List_OnLoadError = function() {
    try {
        $c.win.alert(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS93300.dts_List_OnLoadError" });
    }
};

scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS93300.btn_close_onclick" });
    }
};

scwin.dts_List_OnLoadCompleted = function(rowcount) {
    // alert('dts_List.OnLoadCompleted('+rowcount+')');
};

scwin.grd_Grid_OnDblClick = function(row, colid) {
    try {
        if (row === -1) return;
        scwin.STD_CD_APPL_ID = dtl_ListRes.getCellData(dtl_ListRes.getRowPosition(), "STD_CD_APPL_ID"); // 발행기관  신청 ID   
        if (scwin.STD_CD_APPL_ID === "접수번호없음") return;

        scwin.fn_GetPar = scwin.getParam;

        $c.cm.ins_popupOpen("", "", "ULDINS93600", "신청인정보", "620", "410");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS93300.grd_Grid_OnDblClick" });
    }
};

scwin.grd_Grid_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.grd_Grid_OnDblClick(rowIndex, columnId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS93300.grd_Grid_oncelldblclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 표준코드 처리자 조회
 ***********************************************/
scwin.ins_search = function() {
    ////var queryId = "";
    // 표준코드 처리자 조회 팝업이다. 
    // param1 => 표준코드 STD_CD 

    // alert(frame.Provider("../").vScrenID);

/*
    if ($p.parent().scwin.vScrenID == "ULDINS15900.gfm") {
        queryId = "lds.ins.common.select.listStdCdINDICPrcInquiry"; // 지표일경우 

    } else if ($c.frame.path("../").scwin.vScrenID == "ULDINS15400.gfm") {
        queryId = "lds.ins.common.select.listStdCdFUTOPTPrcInquiry"; // 선물옵션일경우  

    } else {
        queryId = "lds.ins.common.select.listStdCdPrcInquiry";
    }
*/    

    dma_ListReq.set("SCREN_ID", "ULDINS93300.xml");
    dma_ListReq.set("SCREN_PROCES_TP_CD",$c.stf.info("SCREN_PROCS_TP_CD_01"));
    dma_ListReq.set("param01", scwin.param1);
    dma_ListReq.set("param02", scwin.param1);
    dma_ListReq.set("param03", scwin.param1);

    // const res = await $c.sbm.execute(sbm_dts_List, reqMap);
    // dtl_ListRes.setJSON(res);

    // 임시 데이터
    dtl_ListRes.setData(["200508300032","신규신청","홍** (02-3774-9687)","20050830","최초신청","200508300032","처리완료","","","표준코드등록"]);
};

/********************************************** 

 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = scwin.STD_CD_APPL_ID;
    scwin.arrPar[1] = "STD_CD";
    return scwin.arrPar.length;
};
